// Works for both entry points: Gmail attachments (attachment_0, attachment_1...) and the Drive download (data).
const out = [];
for (const item of $input.all()) {
  const files = item.binary || {};
  const key = Object.keys(files).find((k) =>
    (files[k].mimeType || '').includes('pdf') || (files[k].fileName || '').toLowerCase().endsWith('.pdf'));
  if (!key) continue; // not a PDF, nothing to do
  const fromEmail = Boolean(item.json.subject !== undefined || item.json.from);
  out.push({
    json: {
      fileName: files[key].fileName || 'contract.pdf',
      source: fromEmail
        ? 'Email from ' + (item.json.from?.value?.[0]?.address || 'unknown sender') + ': ' + (item.json.subject || '')
        : 'Google Drive',
      link: fromEmail
        ? 'https://mail.google.com/mail/u/0/#all/' + item.json.id
        : (item.json.webViewLink || (item.json.id ? 'https://drive.google.com/file/d/' + item.json.id + '/view' : '')),
    },
    binary: { contract_pdf: files[key] },
  });
}
return out;

