const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
return $input.all().map(({ json }, i) => {
  const src = $('Find the PDF').itemMatching(i).json;
  const c = json.output || {};
  const row = (label, value) => `<tr><td style="padding:6px 12px 6px 0;vertical-align:top;color:#555;white-space:nowrap">${label}</td><td style="padding:6px 0">${esc(value || 'Not stated')}</td></tr>`;
  const parties = (c.parties || []).map((p) => `${esc(p.name)} (${esc(p.role)})`).join('<br>') || 'Not stated';
  const order = { high: 0, medium: 1, low: 2 };
  const risks = (c.risks || []).sort((a, b) => (order[a.severity] ?? 3) - (order[b.severity] ?? 3))
    .map((r) => `<li><strong>${esc((r.severity || '').toUpperCase())}</strong> ${esc(r.clause)}: ${esc(r.why_it_matters)}</li>`).join('');
  const html = `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5;max-width:680px">
<p>${esc(c.plain_summary)}</p>
<table style="border-collapse:collapse">
<tr><td style="padding:6px 12px 6px 0;vertical-align:top;color:#555">Parties</td><td style="padding:6px 0">${parties}</td></tr>
${row('Type', c.contract_type)}${row('Effective', c.effective_date)}${row('Ends', c.end_date)}${row('Term and renewal', c.term_and_renewal)}${row('Notice period', c.notice_period)}${row('Payment terms', c.payment_terms)}${row('Termination', c.termination)}${row('Liability', c.liability_and_indemnity)}${row('Governing law', c.governing_law)}
</table>
<h3 style="margin-top:20px">Worth a second look</h3>
<ul>${risks || '<li>Nothing flagged.</li>'}</ul>
<p style="color:#777;font-size:12px">Source: ${esc(src.source)}. File: ${src.link ? '<a href="' + src.link + '">' + esc(src.fileName) + '</a>' : esc(src.fileName)}.<br>
Generated by AI as a reading aid. It can miss things and is not legal advice.</p></div>`;
  return { json: { subject: `Contract brief: ${c.contract_type || 'contract'} with ${(c.parties || []).map((p) => p.name).slice(0, 2).join(' and ') || src.fileName}`, html } };
});
